import { Artifact } from '@a2a-js/sdk'
import { z } from 'zod'

/** Project contract: pushed by the executor, never generated by client-side polling. */
export const HEARTBEAT_EXTENSION = 'urn:raycloud:a2a:heartbeat:v1'
export const HEARTBEAT_ARTIFACT = 'a2a.heartbeat'
export const Heartbeat = z.object({
  type: z.literal('HEARTBEAT'),
  sequence: z.number().int().positive().safe(),
  timestamp: z.number().int().positive().safe(),
}).strict()
export class HeartbeatProtocolError extends Error {}

export function heartbeatArtifact(taskId: string, sequence: number): Artifact {
  return Artifact.fromJSON({
    artifactId: `${taskId}:heartbeat`, name: HEARTBEAT_ARTIFACT,
    metadata: { extension: HEARTBEAT_EXTENSION },
    parts: [{ data: Heartbeat.parse({ type: 'HEARTBEAT', sequence, timestamp: Date.now() }) }],
  })
}

/** Per-call sequence prevents replayed heartbeats from keeping a dead stream alive. */
export class HeartbeatReader {
  private sequence = 0
  private taskId?: string
  private remoteContextId?: string
  constructor(private readonly contextId?: string) {}

  read(artifact: Artifact, taskId: string, contextId: string, expectedTaskId?: string): boolean | undefined {
    if (artifact.name !== HEARTBEAT_ARTIFACT) return undefined
    const part = artifact.parts[0]
    if (!taskId || !contextId || (expectedTaskId && taskId !== expectedTaskId)
      || (this.contextId && contextId !== this.contextId)
      || (this.taskId && taskId !== this.taskId) || (this.remoteContextId && contextId !== this.remoteContextId)
      || artifact.metadata?.extension !== HEARTBEAT_EXTENSION
      || artifact.parts.length !== 1 || part?.content?.$case !== 'data') {
      throw new HeartbeatProtocolError('A2A HEARTBEAT envelope is invalid or belongs to another task/context')
    }
    const parsed = Heartbeat.safeParse(part.content.value)
    if (!parsed.success) throw new HeartbeatProtocolError('A2A HEARTBEAT data is invalid')
    if (parsed.data.sequence <= this.sequence) return false
    this.taskId = taskId
    this.remoteContextId = contextId
    this.sequence = parsed.data.sequence
    return true
  }
}

export class CallTimeoutError extends Error {}

/** Only validated remote activity renews the idle deadline. No local ping/fallback. */
export class CallLiveness {
  private readonly controller = new AbortController()
  private idle?: ReturnType<typeof setTimeout>
  private maximum?: ReturnType<typeof setTimeout>
  private disposed = false
  readonly signal: AbortSignal

  constructor(private readonly timeoutMs: number, maxDurationMs = 0, parent?: AbortSignal) {
    this.signal = parent ? AbortSignal.any([parent, this.controller.signal]) : this.controller.signal
    this.touch()
    if (maxDurationMs > 0) this.maximum = setTimeout(() => {
      this.controller.abort(new CallTimeoutError(`A2A max duration exceeded after ${maxDurationMs}ms`))
    }, maxDurationMs)
    this.maximum?.unref()
  }

  touch(): void {
    if (this.disposed || this.signal.aborted) return
    clearTimeout(this.idle)
    this.idle = setTimeout(() => this.controller.abort(new CallTimeoutError(
      `A2A idle timeout after ${this.timeoutMs}ms (no progress or HEARTBEAT)`,
    )), this.timeoutMs)
    this.idle.unref()
  }

  dispose(): void {
    this.disposed = true
    clearTimeout(this.idle)
    clearTimeout(this.maximum)
  }
}
